// (字典模型)MDModel1.endLoad
debugger

var dataSet = AGGrid1.getDataSet();
if (dataSet == null) {
   return 1;
}
var count = dataSet.getRowCount();

// 创建对象来存储需要设置的条件
var redRowsCondition = {};  // 行背景条件
var column1Conditions = {};  // Column1 单元格条件
var column13Conditions = {};  // Column13 单元格条件
var column20Conditions = {};  // Column20 单元格条件

var getdate = function () {
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return year + '-' + month + '-' + day; // 返回 2025-11-10 格式
};

var dqrq = getdate();
// 将当前日期转换为int格式进行对比
var currentDateInt = 0;
var currentDateParts = dqrq.split("-");
if (currentDateParts.length === 3) {
    var year = currentDateParts[0];
    var month = currentDateParts[1];
    var day = currentDateParts[2];
    currentDateInt = parseInt(year + month + day);
}

if (count > 0) {
   for (var i = 0; i < count; i++) {
      var row = dataSet.getRowSet(i);
      var pft = row.getValue("PLAN_FINISH_TIME", "");
      var wgrq = row.getValue("wgrq", "");
      var aft = row.getValue("ACTUAL_FINISH_TIME", "");
      var pdi = row.getValue("PART_DRAWING_ID", "");

      // 转换PLAN_FINISH_TIME为int
      var planInt = 0;
      if (pft && pft.toString().trim() !== "") {
         var pftStr = pft.toString().trim();
         if (pftStr.length === 8 && /^\d{8}$/.test(pftStr)) {
            planInt = parseInt(pftStr);
         } else if (pftStr.indexOf("-") > -1) {
            var datePart = pftStr.split(" ")[0];
            var parts = datePart.split("-");
            if (parts.length === 3) {
               var year = parts[0];
               var month = parts[1].padStart(2, '0');
               var day = parts[2].padStart(2, '0');
               planInt = parseInt(year + month + day);
            }
         }
      }

      // 转换wgrq为int
      var wgInt = 0;
      if (wgrq && wgrq.toString().trim() !== "") {
         var wgrqStr = wgrq.toString().trim();

         if (wgrqStr.length === 14 && /^\d{14}$/.test(wgrqStr)) {
            var dateStr = wgrqStr.substring(0, 8);
            wgInt = parseInt(dateStr);
         } else if (wgrqStr.indexOf("-") > -1) {
            var datePart = wgrqStr.split(" ")[0];
            var parts = datePart.split("-");
            if (parts.length === 3) {
               var year = parts[0];
               var month = parts[1].padStart(2, '0');
               var day = parts[2].padStart(2, '0');
               wgInt = parseInt(year + month + day);
            }
         } else if (wgrqStr.length === 8 && /^\d{8}$/.test(wgrqStr)) {
            wgInt = parseInt(wgrqStr);
         }
      }

      // 转换ACTUAL_FINISH_TIME为int
      var actualInt = 0;
      if (aft && aft.toString().trim() !== "") {
         var aftStr = aft.toString().trim();

         if (aftStr.length === 14 && /^\d{14}$/.test(aftStr)) {
            var dateStr = aftStr.substring(0, 8);
            actualInt = parseInt(dateStr);
         } else if (aftStr.indexOf("-") > -1) {
            var datePart = aftStr.split(" ")[0];
            var parts = datePart.split("-");
            if (parts.length === 3) {
               var year = parts[0];
               var month = parts[1].padStart(2, '0');
               var day = parts[2].padStart(2, '0');
               actualInt = parseInt(year + month + day);
            }
         } else if (aftStr.length === 8 && /^\d{8}$/.test(aftStr)) {
            actualInt = parseInt(aftStr);
         }
      }

      // 判断是否需要红色背景
      var needRed = false;
      if (planInt > 0) {
         // 原有的逻辑：如果有实际完成时间或完工日期，且计划完成时间小于等于它们
         if (wgInt > 0 && planInt <= wgInt) {
            needRed = true;
         }

         if (actualInt > 0 && planInt <= actualInt) {
            needRed = true;
         }
         
         // 新增逻辑：如果都没有值（wgInt和actualInt都为0）且当前日期大于计划完成日期
         if (wgInt === 0 && actualInt === 0 && currentDateInt > 0 && currentDateInt > planInt) {
            needRed = true;
         }
      }

      // 如果需要红色背景，添加到条件对象中
      if (needRed) {
         var condition = "PART_DRAWING_ID == '" + pdi + "'";

         // 添加行背景条件
         redRowsCondition[pdi] = condition;

         // 添加Column13条件（总是需要设置）
         column13Conditions[pdi] = condition;

         // 添加Column1条件（当actualInt > 0时）
         if (actualInt > 0) {
            column1Conditions[pdi] = condition;
         }

         // 添加Column20条件（当wgInt > 0时）
         if (wgInt > 0) {
            column20Conditions[pdi] = condition;
         }
      }
   }

   // 批量设置样式
   if (Object.keys(redRowsCondition).length > 0) {

      // 1. 设置行背景色
      var rowConditions = [];
      for (var pdi in redRowsCondition) {
         if (redRowsCondition.hasOwnProperty(pdi)) {
            rowConditions.push(redRowsCondition[pdi]);
         }
      }

      if (rowConditions.length > 0) {
         var rowConditionStr = rowConditions.join(" || ");
         AGGrid1.setState({
            rowBkgColor: { '#EE5757': rowConditionStr }
         });

      }

      // 2. 设置Column13单元格样式
      var column13ConditionsList = [];
      for (var pdi in column13Conditions) {
         if (column13Conditions.hasOwnProperty(pdi)) {
            column13ConditionsList.push(column13Conditions[pdi]);
         }
      }

      if (column13ConditionsList.length > 0) {
         var column13ConditionStr = column13ConditionsList.join(" || ");
         Column13.setCellBackgroundColorMap({ '#EE5757': column13ConditionStr });
         Column13.setCellFontColorMap({ '#FFFF00': column13ConditionStr });

      }

      // 3. 设置Column1单元格样式
      var column1ConditionsList = [];
      for (var pdi in column1Conditions) {
         if (column1Conditions.hasOwnProperty(pdi)) {
            column1ConditionsList.push(column1Conditions[pdi]);
         }
      }

      if (column1ConditionsList.length > 0) {
         var column1ConditionStr = column1ConditionsList.join(" || ");
         Column1.setCellBackgroundColorMap({ '#EE5757': column1ConditionStr });
         Column1.setCellFontColorMap({ '#FFFF00': column1ConditionStr });
      }
      // 4. 设置Column20单元格样式
      var column20ConditionsList = [];

      for (var pdi in column20Conditions) {
         if (column20Conditions.hasOwnProperty(pdi)) {
            column20ConditionsList.push(column20Conditions[pdi]);
         }
      }

      if (column20ConditionsList.length > 0) {
         var column20ConditionStr = column20ConditionsList.join(" || ");
         Column20.setCellBackgroundColorMap({ '#EE5757': column20ConditionStr });
         Column20.setCellFontColorMap({ '#FFFF00': column20ConditionStr });
      }
   }
   // 重绘表格
   AGGrid1.redrawRows();
}

